class CusUpdate(RtgUpdate):
    """Command for execute cus-update procedure."""

    def __init__(self, connection, path="/opt/cus/bin/cus-update", options=None, update_file=None, prompt=None,
                 newline_chars=None, runner=None):
        """
        Cus update command. To execute this script command with -file option you need run it as root.

        :param connection: moler connection to device, terminal when command is executed.
        :param path: Path to cus-update script.
        :param options: parameter with which the command will be executed
        :param update_file: file for -file option if not given script will be run with -nofile option
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CusUpdate, self).__init__(connection, path=path, options=options, update_file=update_file, prompt=prompt,
                                        newline_chars=newline_chars, runner=runner)


